import re

_NUM = r'[0-9]+(?:[.,][0-9]+)?'
_PATTERN = re.compile(
    rf'P(?:(?P<W>{_NUM})W'
    rf'|(?:(?P<D>{_NUM})D)?'
    rf'(?P<T>T(?=[0-9])(?:(?P<H>{_NUM})H)?(?:(?P<M>{_NUM})M)?(?:(?P<S>{_NUM})S)?)?)'
)


def _to_float(s: str) -> float:
    return float(s.replace(',', '.'))


def parse_duration(text: str) -> float:
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    m = _PATTERN.fullmatch(text)
    if m is None:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    if m.group('W') is not None:
        return _to_float(m.group('W')) * 7 * 86400

    components = [
        (m.group('D'), 86400),
        (m.group('H'), 3600),
        (m.group('M'), 60),
        (m.group('S'), 1),
    ]
    present = [(v, mult) for v, mult in components if v is not None]
    if not present:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    # Only the last component written may have a decimal fraction.
    for v, _ in present[:-1]:
        if '.' in v or ',' in v:
            raise ValueError(f"fraction allowed only on last component: {text!r}")

    total = 0.0
    for v, mult in present:
        total += _to_float(v) * mult
    return float(total)
